import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Security and privacy audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/SECURITY-PRIVACY.html"}],["meta",{"property":"og:title","content":"Security and privacy audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/SECURITY-PRIVACY.html"}],["meta",{"name":"twitter:title","content":"Security and privacy audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/SECURITY-PRIVACY.md","filePath":"audits/SECURITY-PRIVACY.md","lastUpdated":1794184492000}`),a={name:`audits/SECURITY-PRIVACY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="security-and-privacy-audit" tabindex="-1">Security and privacy audit <a class="header-anchor" href="#security-and-privacy-audit" aria-label="Permalink to “Security and privacy audit”">​</a></h1><h2 id="sec-01-—-imported-account-ids-are-interpolated-into-html-without-escaping" tabindex="-1">SEC-01 — Imported account IDs are interpolated into HTML without escaping <a class="header-anchor" href="#sec-01-—-imported-account-ids-are-interpolated-into-html-without-escaping" aria-label="Permalink to “SEC-01 — Imported account IDs are interpolated into HTML without escaping”">​</a></h2><p><strong>Severity: P1</strong></p><p><strong>Evidence:</strong></p><ul><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/config-schema.js#L25-L26" target="_blank" rel="noreferrer">config-schema.js L25-L26</a> requires account IDs to be non-empty but does not constrain their characters.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L214" target="_blank" rel="noreferrer">app.js L214</a> parses an imported JSON file, validates its configuration and applies it.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L84" target="_blank" rel="noreferrer">app.js L84</a> uses each imported account object key as the account ID.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L63" target="_blank" rel="noreferrer">app.js L63</a> inserts <code>a.id</code> directly into <code>data-id</code>, radio <code>value</code> and <code>data-remove-account</code> attributes inside an <code>innerHTML</code> template. The local <code>esc</code> helper is used for labels but not for the ID.</li></ul><p><strong>Impact:</strong> a crafted JSON file can supply an account ID containing quotes/HTML and break out of an attribute when the user imports it. This is a client-side DOM-XSS path in the public application origin. It requires the victim to import a malicious scenario file, but the import feature is an explicit untrusted-file boundary.</p><p><strong>Recommendation:</strong></p><ol><li>Escape the ID for every HTML attribute context at render time (at minimum use the existing <code>esc(a.id)</code> consistently).</li><li>Prefer DOM construction and <code>setAttribute</code> over concatenating untrusted values into HTML.</li><li>Consider validating IDs against a documented safe identifier format, but do not rely on validation as a substitute for output encoding.</li><li>Add a regression test importing an account ID such as <code>&quot;&gt;&lt;img src=x onerror=alert(1)&gt;</code> and assert that it is rendered as inert text/attribute data.</li><li>Audit every <code>innerHTML</code> template for imported values and keep report rendering covered by adversarial-label tests.</li></ol><h2 id="positive-security-controls" tabindex="-1">Positive security controls <a class="header-anchor" href="#positive-security-controls" aria-label="Permalink to “Positive security controls”">​</a></h2><ul><li>Imported configuration is JSON-parsed and checked against an allowlisted schema before application.</li><li>Field values are generally inserted using <code>textContent</code> or HTML escaping; the account-ID path is the exception identified above.</li><li>The standalone report escapes dynamic table/ledger/instruction text and protects embedded JSON from closing the script element.</li><li>The worker is a dedicated application-owned worker. Its protocol validates message type, positive safe integer request ID and object payload; using <code>event.origin</code> as worker authentication was correctly avoided.</li><li>The browser app uses a local static catalogue and does not require a backend account/session service.</li><li>No third-party analytics, advertising pixels or session-replay scripts were identified in the reviewed web template.</li></ul><h2 id="priv-01-—-local-scenario-drafts-persist-without-an-in-app-clear-retention-control" tabindex="-1">PRIV-01 — Local scenario drafts persist without an in-app clear/retention control <a class="header-anchor" href="#priv-01-—-local-scenario-drafts-persist-without-an-in-app-clear-retention-control" aria-label="Permalink to “PRIV-01 — Local scenario drafts persist without an in-app clear/retention control”">​</a></h2><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L10" target="_blank" rel="noreferrer">app.js L10</a> defines a localStorage draft key; <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L89-L90" target="_blank" rel="noreferrer">app.js L89-L90</a> saves and restores the scenario.</p><p><strong>Impact:</strong> account labels, balances, inflow/outflow schedules and other personal planning data remain in browser storage until overwritten or manually cleared through browser controls. The app accurately says the draft stays in the browser, but users are not given a clear in-app deletion path or retention explanation.</p><p><strong>Recommendation:</strong> add a visible “Clear saved draft” action with confirmation; explain that drafts remain in this browser profile until cleared. Keep export/import local and avoid transmitting scenario data. Do not add analytics or replay tools without a separate privacy review.</p><h2 id="web-sec-02-—-static-hosting-still-needs-an-explicit-security-header-strategy" tabindex="-1">WEB-SEC-02 — Static hosting still needs an explicit security-header strategy <a class="header-anchor" href="#web-sec-02-—-static-hosting-still-needs-an-explicit-security-header-strategy" aria-label="Permalink to “WEB-SEC-02 — Static hosting still needs an explicit security-header strategy”">​</a></h2><p>GitHub Pages does not provide arbitrary per-route response headers through a repository file in the same way as a configurable origin server. The reviewed app should therefore document which controls are available at the hosting layer and avoid claiming that a <code>robots.txt</code> file is a security boundary. If a stronger Content-Security-Policy, Referrer-Policy or Permissions-Policy is required, use a hosting layer that can emit those headers or an accurately tested meta-policy where suitable. A CSP meta element is not equivalent to a full response header and has limitations.</p><h2 id="privacy-assessment" tabindex="-1">Privacy assessment <a class="header-anchor" href="#privacy-assessment" aria-label="Permalink to “Privacy assessment”">​</a></h2><ul><li>The browser copy states that calculations run locally and drafts stay in the browser.</li><li>The app&#39;s data flows are primarily local catalogue fetches, local storage and a same-origin worker.</li><li>The standalone report is generated client-side and can be saved as a local HTML file.</li><li>No remote analytics or session replay was found in the reviewed source.</li><li>A concise privacy notice should explain local storage, file import/export, local report generation, network requests for static catalogue assets, and how to clear saved data. Avoid generic legal boilerplate that does not match the actual product.</li></ul>`,18)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};